"""Generate the five buildless HTML pages; no framework or runtime build needed."""
from pathlib import Path

ROOT = Path(__file__).parent / 'frontend'
PAGES = [('index', 'Tổng quan', '▦'), ('predict', 'Dự báo 1 đơn', '↗'),
         ('batch', 'Dự báo hàng loạt', '▤'), ('order', 'Chi tiết đơn hàng', '⌕'),
         ('model', 'Model & giám sát', '◷')]


def card(label, node, source):
    return f'<article class="card kpi"><small>{label}</small><strong id="{node}">—</strong><small>{source}</small></article>'


def chart(title, subtitle, node, tag='DELIVERY PREDICTIONS'):
    return f'<article class="card"><div class="card-head"><div><h2>{title}</h2><p class="muted">{subtitle}</p></div><span class="tag">{tag}</span></div><div class="chart"><canvas id="{node}" role="img" aria-label="{title}"></canvas></div></article>'


def threshold():
    return '<div class="threshold"><label for="threshold">Ngưỡng quyết định</label><input id="threshold" type="range" min="0" max="1" step="0.0001" aria-describedby="thresholdHint"><output id="thresholdValue" for="threshold">—</output><button id="resetThreshold" class="btn">Đặt lại</button><span class="muted" id="thresholdHint">Đổi ngưỡng từ điểm đã lưu · không chạy lại model</span></div>'


def heading(title, subtitle, action=''):
    return f'<div class="page-head"><div><p class="eyebrow">DATACO · DELIVERY INTELLIGENCE</p><h1>{title}</h1><p class="subtitle">{subtitle}</p></div>{action}</div>'


