overview += '<article class="card"><div class="card-head"><div><h2>20 dòng có rủi ro cao nhất</h2><p class="muted">Chọn mã đơn để xem toàn bộ các dòng và xác suất cấp đơn.</p></div><span class="tag">TỪ DELIVERY_PREDICTIONS</span></div><div class="table-wrap"><table><thead><tr><th>Mã đơn hàng</th><th>Order item</th><th>Xác suất trễ</th><th>Dự đoán</th><th></th></tr></thead><tbody id="topRows"><tr><td colspan="5" class="empty">Chưa có dữ liệu. Hãy export CSV DataCo.</td></tr></tbody></table></div></article>'

form = ''  # Input fields are generated from the exported API schema.
