predict += '<div class="notice" id="semantics">Ngày đặt hàng tạo tháng và thứ trong tuần; giá trị dòng đơn được log1p đúng như notebook.</div><div class="grid"><article class="card"><div class="card-head"><div><h2>Thông tin đầu vào</h2><p class="muted">* Trường bắt buộc · tiền tệ USD</p></div><span class="tag">KHÔNG TRAIN LẠI</span></div><div class="actions" style="margin:20px 0"><button id="sampleLate" class="btn">Điền đơn mẫu trễ</button><button id="sampleOnTime" class="btn">Điền đơn mẫu không trễ</button></div><form id="predictForm" novalidate><div class="form-grid" id="inputFields">' + form + '</div><div class="form-footer"><button id="predictSubmit" class="btn primary" disabled>Dự báo xác suất ↗</button><span class="muted">Pipeline DataCo · đặc trưng từ notebook</span></div></form></article><div><article class="card result"><h2>Kết quả dự báo</h2><div id="predictionOutput"><p class="empty">Kết quả sẽ xuất hiện ở đây sau khi dự báo.<br>Cần model và bộ feature DataCo hợp lệ.</p></div></article></div></div>'

batch = heading('Dự báo nhiều dòng cùng lúc', 'Tải CSV UTF-8, giữ nguyên mọi dòng và báo rõ lỗi theo số dòng.') + threshold()
batch += '<div class="kpis">' + card('Tổng dòng', 'batchTotal', 'Từ CSV vừa tải') + card('Dự đoán trễ', 'batchLate', 'Theo ngưỡng hiện tại') + card('Tỷ lệ trễ', 'batchRate', 'Trên các dòng hợp lệ') + card('Dòng lỗi', 'batchErrors', 'Không bỏ mất dòng') + '</div><article class="card"><div class="card-head"><div><h2>Tải dữ liệu để chấm điểm</h2><p class="muted">Tối đa 5.000 dòng / 3 MB · không chứa biến sau giao hàng</p></div><button class="btn" id="sampleCsv">↓ Tải CSV mẫu</button></div><form id="batchForm"><div class="upload"><div class="icon">⇧</div><h3>Chọn tệp đơn hàng của bạn</h3><label for="batchFile" class="muted">CSV UTF-8 với các cột như form dự báo một đơn</label><input id="batchFile" type="file" accept=".csv,text/csv" required><p class="muted">Model chạy một lần theo lô, không gọi SHAP cho từng dòng.</p></div><div class="actions"><button class="btn primary" id="batchRun" disabled>Chạy dự báo ↗</button><span class="muted" id="progressLabel" role="status"></span></div><progress id="progress" max="1" hidden aria-label="Tiến độ dự báo"></progress></form></article><article class="card"><div class="card-head"><div><h2>Kết quả chấm điểm</h2><p class="muted">Đổi ngưỡng để phân loại lại ngay, không gọi model.</p></div><div class="actions"><label class="muted"><input id="lateOnly" type="checkbox"> Chỉ đơn trễ</label><button class="btn" id="exportBatch" disabled>↓ Xuất CSV kết quả</button></div></div><div class="table-wrap"><table><thead><tr><th>Dòng CSV</th><th>Order item</th><th>Xác suất</th><th>Dự đoán</th><th>Kiểm tra dữ liệu</th></tr></thead><tbody id="batchRows"><tr><td colspan="5" class="empty">Chưa có kết quả.</td></tr></tbody></table></div><div class="pager"><span id="pageLabel">0 dòng</span><div class="actions"><button class="btn" id="prev" disabled>← Trước</button><button class="btn" id="next" disabled>Sau →</button></div></div></article>'

order = heading('Mọi dòng đơn hàng, một góc nhìn', 'Xác suất rủi ro cấp đơn bằng MAX xác suất các order item.') + threshold()
order += '<article class="card"><h2>Tra cứu mã đơn hàng</h2><form id="orderLookup" class="lookup"><label for="lookupId" class="sr-only">Mã order_id</label><input class="search-input" id="lookupId" placeholder="Nhập order_id trong delivery_predictions.csv" required maxlength="200"><button class="btn primary">Tra cứu đơn ↗</button></form></article><div id="orderResult" hidden><div class="kpis">'+card('Xác suất cấp đơn · MAX','orderProbability','Từ delivery_predictions')+card('Số dòng trong đơn','itemCount','Từ delivery_predictions')+'</div><article class="card"><div class="card-head"><div><h2 id="orderId"></h2><p class="muted">Nhãn cập nhật theo ngưỡng hiện tại</p></div><div id="orderLabel"></div></div><div class="table-wrap"><table><thead><tr><th>Order item</th><th>Tập dữ liệu</th><th>Xác suất trễ</th><th>Dự đoán</th></tr></thead><tbody id="orderRows"></tbody></table></div></article></div>'

model = heading('Mô hình & chất lượng dự báo', 'Theo dõi chỉ số tập test, ngưỡng vận hành và nguồn dữ liệu giám sát.') + threshold()
model += '<article class="card"><div class="card-head"><div><h2 id="modelName">Đang đọc cấu hình</h2><p class="muted">Mô hình đã huấn luyện · không huấn luyện lại trên web</p></div><span class="tag">TẬP TEST</span></div><div class="model-flow"><span>DataCo / order item</span><span>→ <b id="featureCount">—</b> feature</span><span>→ Pipeline được chọn trên Validation</span><span>Ngưỡng Youden: <b id="modelThreshold">—</b></span></div><div class="model-metrics" id="testMetrics"></div><p class="source">Nguồn: model_config.json · chỉ số test tại ngưỡng gốc, không đổi khi kéo ngưỡng.</p></article><div class="grid equal"><article class="card"><h2>Confusion matrix</h2><p class="muted" id="cmSource">Tập test · ngưỡng gốc từ cấu hình</p><div class="cm" id="confusion"></div></article><article class="card"><h2>10 feature quan trọng nhất</h2><p class="muted">Từ artifact model / metadata đã export</p><div id="featureImportance"></div></article></div>'+chart('ROC-AUC theo thời gian','Chỉ hiển thị các phép đo thực có nguồn','aucChart','GIÁM SÁT')+'<div class="notice"><b>Không dùng biến rò rỉ.</b> Cấm actual delivery days, delay_days, delivery_status và mọi thông tin chỉ biết sau giao hàng. Không nhập actual_shipping_days, shipping_delay_days, shipping_date hoặc order_status vào form dự báo.</div>'

model += '<article class="card"><h2>Đối chiếu trên tập Validation</h2><p class="muted">Nguồn: ket_qua_validation_nguong_toi_uu.csv · đây là tập dùng để chọn model và ngưỡng, tách biệt với Test phía trên.</p><div class="model-metrics" id="validationMetrics"><p class="empty">Chưa có bảng kết quả Validation.</p></div></article>'
