QUESTIONS = ['Hiệu năng mô hình trên tập test như thế nào?', 'Tỉ lệ giao hàng trễ tổng quan là bao nhiêu?', 'Tại sao không được dùng biến actual delivery days?', 'Ngưỡng tối ưu Youden đang đặt là bao nhiêu?']
for slug, name, icon in PAGES:
    nav = ''.join(f'<a href="{key}.html" class="{"active" if key==slug else ""}"'+ (' aria-current="page"' if key==slug else '') + f'><span>{symbol}</span>{title}</a>' for key,title,symbol in PAGES)
    suggestions = ''.join(f'<button type="button" data-question>{q}</button>' for q in QUESTIONS)
    page_script = 'overview' if slug == 'index' else slug
    html = f'''<!doctype html>
<html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102c2d"><title>{name} · DataCo Delivery Intelligence</title><link rel="stylesheet" href="css/style.css"><script defer src="js/vendor/chart.umd.js"></script><script defer src="js/api.js"></script><script defer src="js/{page_script}.js"></script></head>
<body><div class="shell"><aside><a class="brand" href="index.html"><i>↗</i>Route<span>IQ</span></a><div class="nav-label">WORKSPACE</div><nav aria-label="Điều hướng chính">{nav}</nav><div class="side-note"><b>Dự báo để chủ động hơn</b>Phát hiện rủi ro giao hàng trễ từ dữ liệu thương mại điện tử DataCo.</div><div class="side-footer">DATACO BRAZIL · ML PROJECT<br>Data → Decisions</div></aside><main><header class="topbar"><span>Workspace / <strong>{name}</strong></span><span class="status" id="connection" role="status">● Đang kết nối</span></header><div class="content"><div id="pageError" class="notice error" role="alert" hidden></div><div id="integrityWarning" class="notice" role="status" hidden></div><div id="artifactWarning" class="notice" role="status" hidden></div>{BODIES[slug]}</div></main></div>
<button id="chatToggle" class="chat-toggle" aria-label="Mở trợ lý AI DataCo" aria-expanded="false" aria-controls="chatDrawer">✧</button><section id="chatDrawer" class="chat" role="dialog" aria-labelledby="chatTitle" hidden><div class="chat-header"><div><b id="chatTitle">Trợ lý đồ án DataCo</b><small>Chỉ dùng tri thức và số liệu đồ án</small></div><button id="chatClose" aria-label="Đóng trò chuyện">×</button></div><div id="chatMessages" class="chat-messages" role="log" aria-live="polite"><div class="message ai">Xin chào! Tôi có thể giúp bạn đọc các chỉ số, hiểu ngưỡng dự báo và quy tắc dữ liệu của đồ án.</div><div class="chat-suggestions">{suggestions}</div></div><form id="chatForm" class="chat-form"><label class="sr-only" for="chatInput">Câu hỏi cho trợ lý</label><input id="chatInput" placeholder="Hỏi về mô hình hoặc dữ liệu…" required maxlength="2000"><button id="chatSend" class="btn primary">Gửi ↗</button></form></section></body></html>'''
    (ROOT / f'{slug}.html').write_text(html, encoding='utf-8')
